function escapeForJSON(str) {
    if (!str) return '';
    return str
      .replace(/\\/g, '\\\\')
      .replace(/"/g, '\\"')
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '\\r')
      .replace(/\t/g, '\\t');
  }

// 1. You need to loop through the items provided by $input
for (const item of $input.all()) {

  // 2. Define your function inside or outside the loop

  // 3. Access data via item.json
  // 4. Use the correct syntax to pull from a previous node

  // 5. Assign the new field back to the item's json object
  item.json.page_content = escapeForJSON(item.json.page_content);
  item.json.prompt = escapeForJSON(item.json.prompt)
  item.json.json_ld = escapeForJSON(JSON.stringify(item.json.json_ld))
  item.json.meta_types = escapeForJSON(item.json.meta_types)
  item.json.meta_description = escapeForJSON(item.json.meta_description)
}

// 6. Return the modified array
return $input.all();

